import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.CWWEQfK7.js";const h=JSON.parse(`{"title":"Architecture and key data flows","description":"Understand how Ershu's five modules cooperate across processes, shared code, storage, and the run lifecycle.","frontmatter":{"page_id":"development-architecture","title":"Architecture and key data flows","description":"Understand how Ershu's five modules cooperate across processes, shared code, storage, and the run lifecycle."},"headers":[],"relativePath":"en/development/architecture.md","filePath":"en/development/architecture.md","lastUpdated":1786290726000}`),r={name:"en/development/architecture.md"};function o(i,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture-and-key-data-flows" tabindex="-1">Architecture and key data flows <a class="header-anchor" href="#architecture-and-key-data-flows" aria-label="Permalink to &quot;Architecture and key data flows&quot;">​</a></h1><p>Ershu consists of four running processes and one shared package. Core is installed into the API, Worker, and MCP environments; it does not listen on a port by itself.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ──HTTP/SSE──&gt; Frontend ──HTTP/SSE──&gt; API ─┐</span></span>
<span class="line"><span>                                                   │</span></span>
<span class="line"><span>MCP client ──Streamable HTTP──&gt; MCP ────────────────┤</span></span>
<span class="line"><span>                                                   │  call shared Core services</span></span>
<span class="line"><span>                         Worker ────────────────────┤</span></span>
<span class="line"><span>                                                   ▼</span></span>
<span class="line"><span>                                 PostgreSQL   Milvus   Redis</span></span>
<span class="line"><span>                                      │          │       │</span></span>
<span class="line"><span>                                      └ persistent ┘       └ short-lived coordination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                         Worker ──read-only workspace──&gt; GitHub / GitLab / local repositories</span></span>
<span class="line"><span>                         Worker ──model channel────────&gt; configured model provider</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>Core in this diagram is not a network hop. API, Worker, and MCP import its models, authorization, and query services into their own processes.</p><h2 id="boundaries-between-the-five-modules" tabindex="-1">Boundaries between the five modules <a class="header-anchor" href="#boundaries-between-the-five-modules" aria-label="Permalink to &quot;Boundaries between the five modules&quot;">​</a></h2><h3 id="core-shared-facts-and-rules" tabindex="-1">Core: shared facts and rules <a class="header-anchor" href="#core-shared-facts-and-rules" aria-label="Permalink to &quot;Core: shared facts and rules&quot;">​</a></h3><p>Core defines database models, migrations, project authorization, run state, repository workspaces, retrieval interfaces, model channels, and runtime-setting contracts. Other backend modules can call those public services, but their HTTP and background-process behavior must not move back into Core.</p><p>PostgreSQL is the business source of truth: users, projects, repositories, access, queue state, document metadata, and setting overrides are persistent there. Milvus stores vectors used by semantic retrieval. Redis supports short-lived caching, leases, and coordination; it is not the source of run results.</p><h3 id="api-the-web-control-plane" tabindex="-1">API: the web control plane <a class="header-anchor" href="#api-the-web-control-plane" aria-label="Permalink to &quot;API: the web control plane&quot;">​</a></h3><p>The API exposes FastAPI routes for OPAQUE login, session cookies, CSRF, project and repository management, model channels, run creation and recovery, documents, search, relationship queries, and administration.</p><p>When creating a run, the API checks project access, analysis type, repository scope, and baseline requirements, then uses Core to store run and queue records. It never analyzes code inside the request process. <code>ershu-api-poller</code> is a separate process in the same repository and coordinates scheduled repository checks with a lease.</p><h3 id="worker-the-analysis-data-plane" tabindex="-1">Worker: the analysis data plane <a class="header-anchor" href="#worker-the-analysis-data-plane" aria-label="Permalink to &quot;Worker: the analysis data plane&quot;">​</a></h3><p>The Worker claims available items from the durable queue, prepares a restricted workspace at the target revision, then builds repository trees, code indexes, knowledge relationships, search indexes, and project documents in stages. It continually stores stage, checkpoint, event, usage, and outcome data so the API can recover state after a disconnected client.</p><p>Read-only repository tools enforce path, file-size, and call-budget limits and do not execute repository scripts. Language services run in controlled environments. Language support and dependency preparation are separate concepts: for example, Java language-service support exists, while automated Maven dependency preparation does not.</p><h3 id="mcp-the-read-only-agent-surface" tabindex="-1">MCP: the read-only agent surface <a class="header-anchor" href="#mcp-the-read-only-agent-surface" aria-label="Permalink to &quot;MCP: the read-only agent surface&quot;">​</a></h3><p>MCP exposes project resolution, documents, trees, code indexes, relationships, search, and context queries over Streamable HTTP. Each request validates a Bearer credential, then applies key scope and project authorization through Core services.</p><p>MCP tools cannot create projects, change repositories, or start runs. State-changing work belongs in the web app or API. The current server registers 27 tools; that count describes this revision and should not become a permanent client constant.</p><h3 id="frontend-the-human-workspace" tabindex="-1">Frontend: the human workspace <a class="header-anchor" href="#frontend-the-human-workspace" aria-label="Permalink to &quot;Frontend: the human workspace&quot;">​</a></h3><p>The frontend is a React single-page application using HTTP and SSE through its API client. It covers login, project selection, repositories and runs, document reading and chat, code search, the knowledge graph, MCP keys, and system administration.</p><p>After a refresh, the frontend restores authentication and reads a durable run snapshot from the API. Live events accelerate updates but are not the sole source of state. The frontend does not know about database or Worker instances directly.</p><h2 id="how-does-a-full-analysis-flow" tabindex="-1">How does a full analysis flow? <a class="header-anchor" href="#how-does-a-full-analysis-flow" aria-label="Permalink to &quot;How does a full analysis flow?&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create request</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ API: authenticate, authorize, validate full-project baseline and repository scope</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Core: persist AnalysisRun and RunQueueItem</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Worker: claim a lease and pin target revisions</span></span>
<span class="line"><span>  │     ├─ prepare read-only workspaces</span></span>
<span class="line"><span>  │     ├─ extract deterministic repository facts</span></span>
<span class="line"><span>  │     ├─ build code, relationship, and search indexes</span></span>
<span class="line"><span>  │     └─ generate project documents through a model channel</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ Core: persist stages, events, checkpoints, usage, and outcome</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ API / Frontend: read final state; MCP: query published results</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>The queue record is the recovery boundary. Worker leases prevent two instances from executing the same item concurrently. If an instance disappears, eligible work can become claimable again. A client must inspect final run state; a successful create response does not mean analysis succeeded.</p><h2 id="how-does-incremental-analysis-preserve-a-project-view" tabindex="-1">How does incremental analysis preserve a project view? <a class="header-anchor" href="#how-does-incremental-analysis-preserve-a-project-view" aria-label="Permalink to &quot;How does incremental analysis preserve a project view?&quot;">​</a></h2><p>The first <code>full_project</code> run pins revisions for every active repository and establishes the baseline. Later incremental runs process changed repositories and revisions while keeping project-level output. The API rejects incremental requests without a baseline.</p><p>Cron polling and webhooks both resolve repository changes before creating an ordinary run. Webhook verification signs the timestamp, a NUL byte, the nonce, another NUL byte, and the raw request body. A proxy or middleware must not rewrite that body first.</p><h2 id="three-paths-for-reading-results" tabindex="-1">Three paths for reading results <a class="header-anchor" href="#three-paths-for-reading-results" aria-label="Permalink to &quot;Three paths for reading results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Primary audience</th><th>Character</th></tr></thead><tbody><tr><td>Frontend</td><td>Team members and administrators</td><td>Full administration, visualization, and interactive tracking</td></tr><tr><td>API</td><td>Automation and frontend development</td><td>State changes plus snapshots and query endpoints</td></tr><tr><td>MCP</td><td>Development agents</td><td>Read-only, project-scoped, and attributable to source</td></tr></tbody></table><p>Preserve these boundaries when evolving the system: state changes in API, long-running work in Worker, shared data and rules in Core, agent retrieval in MCP, and human interaction in frontend.</p><blockquote><p>Sources: module entry points, dependency manifests, import-boundary tests, run queue models, Worker stages, MCP tool registration, and frontend routing.</p></blockquote>`,30)])])}const b=a(r,[["render",o]]);export{h as __pageData,b as default};
